/**
 * Indicates the direction of the activation (based on the previous active tab).
 * @type {'left' | 'right' | 'up' | 'down' | 'none'}
 */
export declare const activationDirection = "data-activation-direction";
/**
 * Indicates the orientation of the tabs.
 * @type {'horizontal' | 'vertical'}
 */
export declare const orientation = "data-orientation";
/**
 * Present when the tab is disabled.
 */
export declare const disabled = "data-disabled";
/**
 * Present when the tab is active.
 */
export declare const active = "data-active";